import { yupResolver } from "@hookform/resolvers/yup";
import { LoadingButton } from "@mui/lab";
import {
  Autocomplete,
  Box,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  FormControlLabel,
  FormHelperText,
  FormLabel,
  Grid,
  IconButton,
  InputAdornment,
  Radio,
  RadioGroup,
  TextField,
  Typography,
} from "@mui/material";
// import CloseIcon from "mdi-material-ui/Close";
import { useEffect, useRef, useState } from "react";
import { Controller, useForm } from "react-hook-form";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import * as yup from "yup";
import { toastError, toastSuccess } from "src/utils/utils";
import ReactQuill from "react-quill";
import "react-quill/dist/quill.snow.css";
import UploadIcon from "@mui/icons-material/Upload";
import CloseIcon from "@mui/icons-material/Close";

const validationSchema = yup.object().shape({
  title: yup.string().required("Title is required"),
  description: yup.string().required("Description is required"),
  logo: yup.string().required("Logo is required"),
  key_words: yup
    .array()
    .of(yup.string().trim().required("Keyword is required"))
    .min(1, "At least one keyword is required")
    .required("Keywords are required"),
});

const FileInput = ({ inputId, accept, onChange, selectedFileName, error }) => (
  <>
    <Button
      startIcon={<UploadIcon />}
      variant="contained"
      sx={{ bgcolor: "#fff", border: "1px solid #6B6B6B", color: "#000" }}
      onClick={() => document.getElementById(inputId).click()}
    >
      Choose File
    </Button>
    <input
      id={inputId}
      name={inputId}
      type="file"
      accept={accept}
      onChange={onChange}
      style={{ display: "none" }}
    />
    <FormHelperText
      variant="body2"
      sx={{ color: "#6B6B6B", marginBottom: "8px" }}
    >
      {selectedFileName || "No file chosen"}
    </FormHelperText>
    <FormHelperText
      variant="body2"
      sx={{ color: "error.main", marginBottom: "8px" }}
    >
      {error && error.message}
    </FormHelperText>
  </>
);

const DialogSuccessStories = (props) => {
  const { open, toggle, dataToEdit, onSuccess, mode } = props;
  const [loading, setLoading] = useState(false);
  const [dialogTitle, setDialogTitle] = useState("");
  const searchTimeoutRef = useRef();
  const [search, setSearch] = useState(null);
  const [keyWords, setKeyWords] = useState([]);
  const [keyWordsInput, setKeyWordsInput] = useState("");
  const {
    control,
    handleSubmit,
    reset,
    setValue,
    formState: { errors },
  } = useForm({
    defaultValues: {
      title: "",
      description: "",
      status: "",
      key_words: [],
    },
    resolver: yupResolver(validationSchema),
    mode: "onChange",
  });
  const [selectedFileNames, setSelectedFileNames] = useState({
    logo: "",
  });
  const [logoImageFile, setLogoImageFile] = useState(null);
  const handleFileChange = (e) => {
    const selectedFile = e.target.files[0];
    if (selectedFile) {
      setLogoImageFile(selectedFile);
      setSelectedFileNames({
        ...selectedFileNames,
        logo: selectedFile.name,
      });
    }
  };
  // const handleAddKeyWords = () => {
  //   if (keyWordsInput.trim()) {
  //     setKeyWords([...keyWords, keyWordsInput.trim()]);
  //     setKeyWordsInput("");
  //   }
  // };

  const handleAddKeyWords = (onChange, currentValue) => {
    if (keyWordsInput.trim()) {
      const newKeyword = keyWordsInput.trim();
      if (typeof newKeyword === "string") {
        const updatedKeyWords = [...currentValue, newKeyword];
        setKeyWords(updatedKeyWords);
        onChange(updatedKeyWords);
      }
      setKeyWordsInput("");
    }
    console.log("currentValue", currentValue);
  };

  // const handleDeleteService = (keyWordToDelete) => {
  //   setKeyWords((prevKeyWord) =>
  //     prevKeyWord.filter((keyWord, index) => index !== keyWordToDelete)
  //   );
  // };

  const handleDeleteService = (keyWordToDelete, onChange) => {
    const updatedKeyWords = keyWords.filter(
      (keyWord, index) => index !== keyWordToDelete
    );

    // Update local state
    setKeyWords(updatedKeyWords);

    // Update the form field value to trigger validation and form state
    onChange(updatedKeyWords);
  };

  const onSubmit = (data) => {
    setLoading(true);

    // const payload = new FormData();
    // payload.append("title", data.title);
    // payload.append("description", data.description);
    // payload.append("key_words", keyWords);

    // if (logoImageFile) {
    //   payload.append("logo", logoImageFile);
    // }
    // if (mode === "edit") {
    //   payload.append("status", data.status);
    // }

    const payload = {
      title: data.title,
      description: data.description,
      key_words: keyWords,
      logo: logoImageFile?.name,
      ...(mode === "edit" && { status: data.status }),
    };
    let apiInstance = null;
    if (mode === "edit") {
      apiInstance = axiosInstance.patch(
        ApiEndPoints.SuccessStories.edit(dataToEdit.id),
        payload
      );
    } else {
      apiInstance = axiosInstance.post(
        ApiEndPoints.SuccessStories.create,
        payload
      );
    }
    apiInstance
      .then((response) => response.data)
      .then((response) => {
        onSuccess();
        toastSuccess(response.message);
        toggle();
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  useEffect(() => {
    if (open) {
      setLoading(false);
      setDialogTitle(mode === "add" ? "Add Stories" : "Edit Stories");
      setKeyWords(
        Array.isArray(dataToEdit?.key_words) ? dataToEdit?.key_words : []
      );
      if (mode === "edit" && dataToEdit) {
        setSelectedFileNames({
          logo: dataToEdit?.logo || "",
        });
        setLogoImageFile(null);
      } else {
        setSelectedFileNames({ logo: "" });
        setLogoImageFile(null);
      }
      reset({
        title: dataToEdit?.title || "",
        description: dataToEdit?.description || "",
        status: dataToEdit?.status || "",
        key_words: dataToEdit?.key_words || [],
      });
    }
  }, [dataToEdit, mode, open, reset]);

  const handleSearchChange = (e) => {
    if (searchTimeoutRef.current) {
      clearTimeout(searchTimeoutRef.current);
    }

    searchTimeoutRef.current = setTimeout(() => {
      setSearch(e.target.value);
    }, 500);
  };

  return (
    <>
      <Dialog open={open} fullWidth maxWidth="sm" scroll="paper">
        <DialogTitle
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <Box>{dialogTitle}</Box>
          <IconButton
            aria-label="close"
            onClick={toggle}
            sx={{ color: (theme) => theme.palette.grey[500] }}
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <DialogContent
          sx={{ pb: 8, px: { sx: 8, sm: 15 }, pt: { xs: 8, sm: 12.5 } }}
        >
          <form id="form" onSubmit={handleSubmit(onSubmit)}>
            <Grid container spacing={4}>
              <Grid item xs={12}>
                <FormControl fullWidth>
                  <FormLabel htmlFor="title" error={Boolean(errors.title)}>
                    Title
                  </FormLabel>
                  <Controller
                    name="title"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <TextField
                        placeholder="Enter Title"
                        multiline
                        value={value}
                        onChange={onChange}
                        error={Boolean(errors.title)}
                        InputLabelProps={{ shrink: true }}
                      />
                    )}
                  />
                  {errors.title && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.title.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>
              <Grid item xs={12}>
                <FormControl fullWidth>
                  <FormLabel
                    htmlFor="key_words"
                    error={Boolean(errors.key_words)}
                  >
                    Departments
                  </FormLabel>
                  <Controller
                    name="key_words"
                    control={control}
                    defaultValue={[]} // Should be an array
                    render={({ field: { value, onChange } }) => (
                      <>
                        <TextField
                          multiline
                          type="text"
                          variant="standard"
                          onChange={(e) => {
                            setKeyWordsInput(e.target.value); // Update only input
                          }}
                          id="key_words"
                          value={keyWordsInput} // Input for adding a new keyword
                          InputProps={{
                            endAdornment: (
                              <InputAdornment position="end">
                                <IconButton
                                  disableRipple
                                  onClick={() =>
                                    handleAddKeyWords(onChange, value)
                                  }
                                >
                                  <Typography fontWeight={700}>Add</Typography>
                                </IconButton>
                              </InputAdornment>
                            ),
                          }}
                        />
                        <Box
                          sx={{
                            display: "flex",
                            gap: "12px",
                            width: "100%",
                            flexWrap: "wrap",
                            mt: 2,
                          }}
                        >
                          {keyWords?.map((keyWord, index) => (
                            <Chip
                              key={index}
                              label={
                                typeof keyWord === "string"
                                  ? keyWord
                                  : "Invalid keyword"
                              }
                              sx={{
                                backgroundColor: "#602de1c2",
                                color: "#ffff",
                                height: "40px",
                                borderRadius: "50px",
                                fontSize: "14px",
                                p: 1,
                              }}
                              onDelete={() =>
                                handleDeleteService(index, onChange)
                              }
                              deleteIcon={<CloseIcon sx={{ fill: "#ffff" }} />}
                            />
                          ))}
                        </Box>
                      </>
                    )}
                  />

                  {errors.key_words && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.key_words.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>

              <Grid item xs={12}>
                <FormControl fullWidth>
                  <FormLabel htmlFor="logo" error={Boolean(errors.logo)}>
                    Logo
                  </FormLabel>
                  <Controller
                    name="logo"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <FileInput
                        inputId="logo" // Corrected inputId to 'author_image'
                        accept=".jpg, .jpeg, .png, .pdf"
                        onChange={(e) => handleFileChange(e)}
                        selectedFileName={selectedFileNames.logo}
                        // error={Boolean(errors.author_image)}
                        error={errors.logo}
                      />
                    )}
                  />
                </FormControl>
              </Grid>
              <Grid item xs={12}>
                <FormControl fullWidth>
                  <FormLabel
                    htmlFor="description"
                    error={Boolean(errors.description)}
                  >
                    Description
                  </FormLabel>
                  <Controller
                    name="description"
                    control={control}
                    render={({ field }) => (
                      <ReactQuill
                        theme="snow"
                        {...field}
                        modules={{
                          toolbar: [
                            [{ header: [1, 2, 3, 4, 5, 6, false] }],
                            ["bold", "italic", "underline", "strike"],
                            ["blockquote", "code-block"],
                            [{ list: "ordered" }, { list: "bullet" }],
                            [{ script: "sub" }, { script: "super" }],
                            [{ indent: "-1" }, { indent: "+1" }],
                            [{ direction: "rtl" }],
                            [{ size: ["small", false, "large", "huge"] }],
                            [{ color: [] }, { background: [] }],
                            [{ font: [] }],
                            ["link"],
                            ["clean"],
                          ],
                        }}
                        formats={[
                          "header",
                          "font",
                          "size",
                          "bold",
                          "italic",
                          "underline",
                          "strike",
                          "blockquote",
                          "list",
                          "bullet",
                          "indent",
                          "script",
                          "link",
                          "color",
                          "background",
                        ]}
                        onChange={(value) => {
                          setValue("description", value, {
                            shouldValidate: true,
                          });
                          field.onChange(value);
                        }}
                      />
                    )}
                  />
                  {errors.description && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.description.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>
              {mode === "edit" && (
                <Grid item xs={12}>
                  <FormControl fullWidth>
                    <FormLabel
                      required
                      htmlFor="status"
                      error={Boolean(errors.status)}
                    >
                      Status
                    </FormLabel>
                    <Controller
                      name="status"
                      control={control}
                      render={({ field: { value, onChange } }) => (
                        <RadioGroup
                          row
                          name="status"
                          onChange={onChange}
                          value={value}
                        >
                          <FormControlLabel
                            value={"active"}
                            control={<Radio />}
                            label="Active"
                          />
                          <FormControlLabel
                            value={"inactive"}
                            control={<Radio />}
                            label="Inactive"
                          />
                        </RadioGroup>
                      )}
                    />
                    {errors.status && (
                      <FormHelperText sx={{ color: "error.main" }}>
                        {errors.status.message}
                      </FormHelperText>
                    )}
                  </FormControl>
                </Grid>
              )}
            </Grid>
          </form>
        </DialogContent>
        <DialogActions>
          <LoadingButton
            size="large"
            type="submit"
            form="form"
            variant="contained"
            loading={loading}
          >
            Submit
          </LoadingButton>
          <Button size="large" variant="outlined" onClick={toggle}>
            Cancel
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default DialogSuccessStories;
